package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="sesiones_caja") public class SesionCaja {
 @Id @GeneratedValue private UUID id; @Column(name="numero_cierre") private String numeroCierre; @Column(name="empresa_id",nullable=false) private UUID empresaId; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="sucursal_id",nullable=false) private Sucursal sucursal; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="caja_id") private Caja caja; @Column(nullable=false) private String numero; @Column(nullable=false) private String estado="OPEN"; @Column(name="abierto_por",nullable=false) private UUID abiertoPor; @Column(name="abierto_en",nullable=false) private LocalDateTime abiertoEn=LocalDateTime.now(); @Column(name="fondo_inicial",nullable=false) private BigDecimal fondoInicial; @Column(name="nota_apertura") private String notaApertura; @Column(name="efectivo_esperado") private BigDecimal efectivoEsperado; @Column(name="efectivo_contado") private BigDecimal efectivoContado; private BigDecimal diferencia; @Column(name="cerrado_por") private UUID cerradoPor; @Column(name="cerrado_en") private LocalDateTime cerradoEn; @Column(name="nota_cierre") private String notaCierre; @Column(name="motivo_diferencia") private String motivoDiferencia; @Column(name="clave_cierre") private String claveCierre; @Version private Long version;
 public UUID getId(){return id;} public String getNumeroCierre(){return numeroCierre;} public void setNumeroCierre(String v){numeroCierre=v;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public Sucursal getSucursal(){return sucursal;} public void setSucursal(Sucursal v){sucursal=v;} public Caja getCaja(){return caja;} public void setCaja(Caja v){caja=v;} public String getNumero(){return numero;} public void setNumero(String v){numero=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} public UUID getAbiertoPor(){return abiertoPor;} public void setAbiertoPor(UUID v){abiertoPor=v;} public LocalDateTime getAbiertoEn(){return abiertoEn;} public void setAbiertoEn(LocalDateTime v){abiertoEn=v;} public BigDecimal getFondoInicial(){return fondoInicial;} public void setFondoInicial(BigDecimal v){fondoInicial=v;} public String getNotaApertura(){return notaApertura;} public void setNotaApertura(String v){notaApertura=v;} public BigDecimal getEfectivoEsperado(){return efectivoEsperado;} public void setEfectivoEsperado(BigDecimal v){efectivoEsperado=v;} public BigDecimal getEfectivoContado(){return efectivoContado;} public void setEfectivoContado(BigDecimal v){efectivoContado=v;} public BigDecimal getDiferencia(){return diferencia;} public void setDiferencia(BigDecimal v){diferencia=v;} public UUID getCerradoPor(){return cerradoPor;} public void setCerradoPor(UUID v){cerradoPor=v;} public LocalDateTime getCerradoEn(){return cerradoEn;} public void setCerradoEn(LocalDateTime v){cerradoEn=v;} public String getNotaCierre(){return notaCierre;} public void setNotaCierre(String v){notaCierre=v;} public String getMotivoDiferencia(){return motivoDiferencia;} public void setMotivoDiferencia(String v){motivoDiferencia=v;} public String getClaveCierre(){return claveCierre;} public void setClaveCierre(String v){claveCierre=v;}
}
